/bin/bash -lc "python - <<'PY'
import bioblend, inspect
from bioblend.galaxy import GalaxyInstance
from bioblend.galaxy.histories import HistoryClient
print('bioblend', getattr(bioblend, '__version__', 'unknown'))
print([x for x in dir(HistoryClient) if 'histor' in x.lower() or 'copy' in x.lower() or 'clone' in x.lower()])
for x in dir(HistoryClient):
    if 'histor' in x.lower() or 'copy' in x.lower() or 'clone' in x.lower():
        o=getattr(HistoryClient,x)
        if callable(o):
            try: print('\\n'+x, inspect.signature(o))
            except Exception: pass
PY"

/bin/bash -lc "python - <<'PY'
import bioblend, inspect
from bioblend.galaxy import GalaxyInstance
from bioblend.galaxy.histories import HistoryClient
print('bioblend', getattr(bioblend, '__version__', 'unknown'))
print([x for x in dir(HistoryClient) if 'histor' in x.lower() or 'copy' in x.lower() or 'clone' in x.lower()])
for x in dir(HistoryClient):
    if 'histor' in x.lower() or 'copy' in x.lower() or 'clone' in x.lower():
        o=getattr(HistoryClient,x)
        if callable(o):
            try: print('\\n'+x, inspect.signature(o))
            except Exception: pass
PY"

